// PAWS OFF! -- sound.
//
// Grown out of the snd1_demo example: the four DMG tone generators, driven
// by a tiny tracker.  Channel 1 is reserved for sound effects (it has the
// sweep unit), channel 2 plays the melody, channel 3 (wave) the bass line and
// channel 4 (noise) the drums.  Songs are generated by tools/mkgfx.py.

#include <tonc.h>
#include "gfx.h"
#include "sound.h"

typedef struct {
  const u8 *start, *p;
  u8 wait, done;
} Track;

static Track trk[3];
static const Song *song;
static int song_id = -1;
static int tick, tempo_adj;
static int noise_hold;

static const u8 *sfx_p;
static int sfx_wait;
static u16 sfx_cnt;

#define N(semi, oct) (((oct) - 2) * 12 + (semi) + 1)
#define END 255
enum { C_, CS, D_, DS, E_, F_, FS, G_, GS, A_, AS, B_ };

typedef struct {
  u16 sweep, cnt;
  const u8 *seq;
} SfxDef;

static const u8 sq_throw[] = {N(A_, 4), 7, END};
static const u8 sq_pickup[] = {N(B_, 5), 3, N(E_, 6), 7, END};
static const u8 sq_hit[] = {N(E_, 6), 2,        N(G_, 6), 2,  N(B_, 6),
                            2,        N(E_, 7), 6,        END};
static const u8 sq_lure[] = {N(C_, 6), 3, N(E_, 6), 5, END};
static const u8 sq_steal[] = {N(A_, 5), 4,        N(DS, 5), 4,  N(A_, 5),
                              4,        N(DS, 5), 8,        END};
static const u8 sq_recover[] = {N(C_, 6), 3,        N(E_, 6), 3,  N(G_, 6),
                                3,        N(C_, 7), 8,        END};
static const u8 sq_lost[] = {N(A_, 4), 28, END};
static const u8 sq_disco[] = {N(C_, 6), 2, N(E_, 6), 2, N(G_, 6), 2,
                              N(C_, 7), 2, N(E_, 7), 2, N(G_, 7), 2,
                              N(E_, 7), 2, N(C_, 7), 2, N(G_, 6), 2,
                              N(C_, 7), 6, END};
static const u8 sq_menu[] = {N(E_, 6), 3, END};
static const u8 sq_ok[] = {N(E_, 6), 3, N(A_, 6), 6, END};
static const u8 sq_empty[] = {N(C_, 4), 3, 0, 2, N(C_, 4), 4, END};
static const u8 sq_pounce[] = {N(E_, 5), 8, END};

static const SfxDef sfx_defs[SFX_COUNT] = {
    {0x0024, SSQR_ENV_BUILD(10, 0, 1) | SSQR_DUTY1_2, sq_throw}, // rising chirp
    {SSW_OFF, SSQR_ENV_BUILD(11, 0, 2) | SSQR_DUTY1_2, sq_pickup},
    {SSW_OFF, SSQR_ENV_BUILD(12, 0, 2) | SSQR_DUTY1_4, sq_hit},
    {SSW_OFF, SSQR_ENV_BUILD(9, 0, 2) | SSQR_DUTY1_4, sq_lure},
    {SSW_OFF, SSQR_ENV_BUILD(13, 0, 4) | SSQR_DUTY1_2, sq_steal},
    {SSW_OFF, SSQR_ENV_BUILD(12, 0, 3) | SSQR_DUTY1_2, sq_recover},
    {0x007C, SSQR_ENV_BUILD(13, 0, 5) | SSQR_DUTY1_2,
     sq_lost}, // long falling wail
    {SSW_OFF, SSQR_ENV_BUILD(11, 0, 3) | SSQR_DUTY1_8, sq_disco},
    {SSW_OFF, SSQR_ENV_BUILD(8, 0, 1) | SSQR_DUTY1_4, sq_menu},
    {SSW_OFF, SSQR_ENV_BUILD(10, 0, 2) | SSQR_DUTY1_4, sq_ok},
    {SSW_OFF, SSQR_ENV_BUILD(9, 0, 1) | SSQR_DUTY1_2, sq_empty},
    {0x001B, SSQR_ENV_BUILD(9, 0, 1) | SSQR_DUTY1_4,
     sq_pounce}, // falling swoosh
};

void snd_init(void) {
  REG_SNDSTAT = SSTAT_ENABLE;
  REG_SNDDMGCNT =
      SDMG_BUILD_LR(SDMG_SQR1 | SDMG_SQR2 | SDMG_WAVE | SDMG_NOISE, 7);
  REG_SNDDSCNT = SDS_DMG100;
  REG_SND1SWEEP = SSW_OFF;

  // A soft triangle for the bass.  Wave RAM writes land in the bank that
  // is *not* selected, so select bank 1, fill bank 0, then switch back.
  REG_SND3SEL = 0x0040;
  REG_WAVE_RAM0 = 0x67452301;
  REG_WAVE_RAM1 = 0xEFCDAB89;
  REG_WAVE_RAM2 = 0x98BADCFE;
  REG_WAVE_RAM3 = 0x10325476;
  REG_SND3SEL = 0x0080;
  REG_SND3CNT = 0;
}

void music_stop(void) {
  song = NULL;
  song_id = -1;
  REG_SND2CNT = 0;
  REG_SND3CNT = 0;
}

void music_tempo(int adj) { tempo_adj = adj; }

void music_play(int id) {
  if (id == song_id && song && song->loop)
    return;
  music_stop();
  song = &songs[id];
  song_id = id;
  trk[0].start = trk[0].p = song->mel;
  trk[1].start = trk[1].p = song->bass;
  trk[2].start = trk[2].p = song->drums;
  trk[0].wait = trk[1].wait = trk[2].wait = 0;
  trk[0].done = trk[1].done = trk[2].done = 0;
  tick = 100; // fire the first tick right away
}

static void note_on(int ch, int n) {
  int soft = (song_id == SONG_TITLE);
  switch (ch) {
  case 0: // melody: plucked square
    if (n == 0)
      break; // let the envelope ring out
    REG_SND2CNT = soft ? (SSQR_ENV_BUILD(9, 0, 5) | SSQR_DUTY1_2)
                       : (SSQR_ENV_BUILD(11, 0, 2) | SSQR_DUTY1_4);
    REG_SND2FREQ = SFREQ_RESET | snd_rates[n];
    break;
  case 1: // bass: wave channel sounds an octave below the squares
    if (n == 0) {
      REG_SND3CNT = 0;
      break;
    }
    REG_SND3SEL = 0x0080;
    REG_SND3CNT = soft ? 0x4000 : 0x2000;
    REG_SND3FREQ = SFREQ_RESET | snd_rates[n + 12];
    break;
  case 2: // drums
    if (n == 0 || noise_hold)
      break;
    switch (n) {
    case 1:
      REG_SND4CNT = SSQR_ENV_BUILD(5, 0, 1);
      REG_SND4FREQ = SFREQ_RESET | 0x11;
      break; // hat
    case 2:
      REG_SND4CNT = SSQR_ENV_BUILD(9, 0, 2);
      REG_SND4FREQ = SFREQ_RESET | 0x42;
      break; // snare
    case 3:
      REG_SND4CNT = SSQR_ENV_BUILD(11, 0, 1);
      REG_SND4FREQ = SFREQ_RESET | 0x65;
      break; // kick
    case 4:
      REG_SND4CNT = SSQR_ENV_BUILD(6, 0, 3);
      REG_SND4FREQ = SFREQ_RESET | 0x11;
      break; // open hat
    }
    break;
  }
}

static void music_tick(void) {
  int i, done = 0;
  for (i = 0; i < 3; i++) {
    Track *t = &trk[i];
    if (t->done) {
      done++;
      continue;
    }
    if (t->wait == 0) {
      if (*t->p == END) {
        if (!song->loop) {
          t->done = 1;
          note_on(i, 0);
          continue;
        }
        t->p = t->start;
      }
      note_on(i, t->p[0]);
      t->wait = t->p[1];
      t->p += 2;
    }
    t->wait--;
  }
  if (done == 3)
    music_stop();
}

void sfx_play(int id) {
  const SfxDef *d = &sfx_defs[id];
  REG_SND1SWEEP = d->sweep;
  sfx_cnt = d->cnt;
  sfx_p = d->seq;
  sfx_wait = 0;
}

void sfx_noise(int cnt, int freq, int hold) {
  REG_SND4CNT = cnt;
  REG_SND4FREQ = SFREQ_RESET | freq;
  noise_hold = hold;
}

void snd_update(void) {
  if (noise_hold)
    noise_hold--;

  if (sfx_p) {
    if (sfx_wait == 0) {
      int n = *sfx_p++;
      if (n == END)
        sfx_p = NULL;
      else {
        sfx_wait = *sfx_p++;
        if (n) {
          REG_SND1CNT = sfx_cnt;
          REG_SND1FREQ = SFREQ_RESET | snd_rates[n];
        } else
          REG_SND1CNT = 0;
      }
    }
    if (sfx_wait)
      sfx_wait--;
  }

  if (song) {
    int tempo = song->tempo + tempo_adj;
    if (++tick >= tempo) {
      tick = 0;
      music_tick();
    }
  }
}
